DO $fresh_guard$
BEGIN
  IF current_user IS DISTINCT FROM 'preflight_owner' OR session_user IS DISTINCT FROM 'preflight_owner' THEN
    RAISE EXCEPTION 'unexpected administrator session';
  END IF;
  IF current_setting('server_version_num')::integer NOT BETWEEN 160000 AND 169999
     OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolcreaterole AND NOT rolsuper)
     OR NOT pg_catalog.has_database_privilege(current_user,current_database(),'CREATE') THEN
    RAISE EXCEPTION 'PostgreSQL 16 non-superuser CREATEROLE/database CREATE contract required';
  END IF;
  IF pg_catalog.to_regnamespace('preflight_team') IS NOT NULL
     OR EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname IN ('preflight_runtime','preflight_team_api_owner')) THEN
    RAISE EXCEPTION 'fresh schema and roles required; do not replace existing deployment';
  END IF;
  IF pg_catalog.to_regprocedure('pg_catalog.sha256(bytea)') IS NULL
     OR encode(sha256('abc'::bytea),'hex') <> 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad' THEN
    RAISE EXCEPTION 'built-in SHA-256 contract unavailable';
  END IF;
  IF current_setting('log_statement') IS DISTINCT FROM 'none'
     OR current_setting('log_parameter_max_length_on_error') IS DISTINCT FROM '0' THEN
    RAISE EXCEPTION 'review administrator SQL logging before installation';
  END IF;
END $fresh_guard$

CREATE OR REPLACE FUNCTION "preflight_team"._api_stamp(value text) RETURNS timestamptz
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
BEGIN
  IF value IS NULL OR length(value) > 40 OR value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid timestamp';
  END IF;
  RETURN value::timestamptz;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid timestamp';
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team"._api_state(rev bigint, doc jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE entry record;
BEGIN
  IF rev IS NULL OR rev < 0 OR jsonb_typeof(doc) IS DISTINCT FROM 'object'
     OR doc - ARRAY['schema_version','revision','queue','accounts','keys','receipts'] <> '{}'::jsonb
     OR doc->'schema_version' IS DISTINCT FROM '1'::jsonb
     OR doc->'revision' IS DISTINCT FROM to_jsonb(rev)
     OR jsonb_typeof(doc->'queue') IS DISTINCT FROM 'string'
     OR jsonb_typeof(doc->'accounts') IS DISTINCT FROM 'object'
     OR jsonb_typeof(doc->'keys') IS DISTINCT FROM 'object'
     OR jsonb_typeof(doc->'receipts') IS DISTINCT FROM 'object'
     OR doc#>>'{accounts,acct_owner,role}' IS DISTINCT FROM 'owner' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT500', MESSAGE = 'invalid workspace';
  END IF;
  FOR entry IN SELECT key, value FROM jsonb_each(doc->'accounts') LOOP
    IF jsonb_typeof(entry.value) IS DISTINCT FROM 'object'
       OR entry.value - ARRAY['id','name','role','active','created_at'] <> '{}'::jsonb
       OR entry.value->>'id' IS DISTINCT FROM entry.key
       OR jsonb_typeof(entry.value->'name') IS DISTINCT FROM 'string'
       OR jsonb_typeof(entry.value->'active') IS DISTINCT FROM 'boolean'
       OR (entry.value->>'role') IS NULL OR (entry.value->>'role') NOT IN ('owner','reviewer','adjudicator')
       OR (entry.key <> 'acct_owner' AND (entry.key !~ '^acct_[0-9a-f]{32}$' OR entry.value->>'role' = 'owner')) THEN
      RAISE EXCEPTION USING ERRCODE = 'PT500', MESSAGE = 'invalid workspace account';
    END IF;
    PERFORM "preflight_team"._api_stamp(entry.value->>'created_at');
  END LOOP;
  FOR entry IN SELECT key, value FROM jsonb_each(doc->'keys') LOOP
    IF entry.key !~ '^[0-9a-f]{64}$' OR jsonb_typeof(entry.value) IS DISTINCT FROM 'object'
       OR entry.value - ARRAY['account_id','expires_at'] <> '{}'::jsonb
       OR jsonb_typeof(entry.value->'account_id') IS DISTINCT FROM 'string'
       OR NOT (doc->'accounts' ? (entry.value->>'account_id')) THEN
      RAISE EXCEPTION USING ERRCODE = 'PT500', MESSAGE = 'invalid workspace key';
    END IF;
    PERFORM "preflight_team"._api_stamp(entry.value->>'expires_at');
  END LOOP;
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team"._api_command(rid uuid, command_text text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE cmd jsonb; action text; payload jsonb; allowed text[]; required text[]; entry record; expected text;
BEGIN
  IF rid IS NULL OR command_text IS NULL OR octet_length(convert_to(command_text,'UTF8')) > 1000000 THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid command';
  END IF;
  BEGIN cmd := command_text::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid command';
  END;
  IF jsonb_typeof(cmd) IS DISTINCT FROM 'object' OR cmd - ARRAY['action','payload'] <> '{}'::jsonb
     OR jsonb_typeof(cmd->'action') IS DISTINCT FROM 'string' OR jsonb_typeof(cmd->'payload') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid command';
  END IF;
  action := cmd->>'action'; payload := cmd->'payload';
  CASE action
    WHEN 'overview','accounts','claim','disagreements' THEN allowed := ARRAY[]::text[]; required := allowed;
    WHEN 'view','release' THEN allowed := ARRAY['item_id']; required := allowed;
    WHEN 'export' THEN allowed := ARRAY['include_synthetic']; required := ARRAY[]::text[];
    WHEN 'create_account' THEN allowed := ARRAY['account_id','name','role','key_digest']; required := allowed;
    WHEN 'replace_key' THEN allowed := ARRAY['account_id','key_digest']; required := allowed;
    WHEN 'set_active' THEN allowed := ARRAY['account_id','active']; required := allowed;
    WHEN 'enqueue_ad' THEN allowed := ARRAY['dataset_id','copy','product_name','category','facts','landing_text','synthetic']; required := ARRAY['dataset_id','copy','category','synthetic'];
    WHEN 'enqueue_run' THEN allowed := ARRAY['run','landing_text','synthetic']; required := ARRAY['run','synthetic'];
    WHEN 'submit' THEN allowed := ARRAY['item_id','decision','rule_ids','cited_spans','rationale']; required := ARRAY['item_id','decision'];
    WHEN 'adjudicate' THEN allowed := ARRAY['item_id','decision','rule_ids','cited_spans','rationale']; required := ARRAY['item_id','decision','rationale'];
    ELSE RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'unknown action';
  END CASE;
  IF payload - allowed <> '{}'::jsonb OR NOT (payload ?& required) THEN
    RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid command fields';
  END IF;
  FOR entry IN SELECT key, value FROM jsonb_each(payload) LOOP
    expected := CASE WHEN entry.key IN ('active','synthetic','include_synthetic') THEN 'boolean'
                     WHEN entry.key IN ('facts','rule_ids','cited_spans') THEN 'array'
                     WHEN entry.key IN ('copy','run') THEN 'object' ELSE 'string' END;
    IF jsonb_typeof(entry.value) IS DISTINCT FROM expected THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid command field type';
    END IF;
  END LOOP;
  RETURN cmd;
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team"._api_auth(doc jsonb, access_key text, action text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE digest text; credential jsonb; actor jsonb; role_name text; permitted text[];
BEGIN
  IF access_key IS NULL OR access_key !~ '^pfk_[A-Za-z0-9_-]{43}$' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT401', MESSAGE = 'access denied';
  END IF;
  digest := encode(sha256(convert_to(access_key,'UTF8')),'hex');
  credential := doc->'keys'->digest;
  actor := doc->'accounts'->(credential->>'account_id');
  IF credential IS NULL OR actor IS NULL OR actor->'active' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION USING ERRCODE = 'PT401', MESSAGE = 'access denied';
  END IF;
  IF "preflight_team"._api_stamp(credential->>'expires_at') <= clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = 'PT401', MESSAGE = 'access denied';
  END IF;
  role_name := actor->>'role';
  permitted := CASE role_name
    WHEN 'owner' THEN ARRAY['overview','accounts','create_account','replace_key','set_active','enqueue_ad','enqueue_run','export']
    WHEN 'reviewer' THEN ARRAY['overview','claim','view','release','submit']
    WHEN 'adjudicator' THEN ARRAY['overview','disagreements','adjudicate','export'] ELSE ARRAY[]::text[] END;
  IF action IS NULL OR NOT (action = ANY(permitted)) THEN
    RAISE EXCEPTION USING ERRCODE = 'PT403', MESSAGE = 'action denied';
  END IF;
  RETURN actor;
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team"._api_auth_delta(old_doc jsonb, new_doc jsonb, actor jsonb, cmd jsonb, stamp timestamptz) RETURNS void
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE action text := cmd->>'action'; p jsonb := cmd->'payload'; target text := p->>'account_id';
        accounts jsonb := old_doc->'accounts'; keys jsonb := old_doc->'keys'; account jsonb;
        digest text := p->>'key_digest'; issued jsonb; days integer;
BEGIN
  IF action NOT IN ('create_account','replace_key','set_active') THEN
    IF new_doc->'accounts' IS DISTINCT FROM accounts OR new_doc->'keys' IS DISTINCT FROM keys THEN
      RAISE EXCEPTION USING ERRCODE = 'PT403', MESSAGE = 'authentication state is immutable';
    END IF;
    RETURN;
  END IF;
  IF actor->>'role' IS DISTINCT FROM 'owner' THEN
    RAISE EXCEPTION USING ERRCODE = 'PT403', MESSAGE = 'owner required';
  END IF;
  IF action = 'create_account' THEN
    IF target IS NULL OR target !~ '^acct_[0-9a-f]{32}$' OR accounts ? target
       OR (p->>'role') NOT IN ('reviewer','adjudicator')
       OR length(btrim(p->>'name')) NOT BETWEEN 1 AND 40
       OR EXISTS (SELECT 1 FROM jsonb_each(accounts) a WHERE lower(a.value->>'name') = lower(p->>'name'))
       OR (SELECT count(*) FROM jsonb_object_keys(accounts)) >= 100 THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid account creation';
    END IF;
    account := new_doc->'accounts'->target;
    IF account->>'id' IS DISTINCT FROM target OR account->>'name' IS DISTINCT FROM p->>'name'
       OR account->>'role' IS DISTINCT FROM p->>'role' OR account->'active' IS DISTINCT FROM 'true'::jsonb
       OR "preflight_team"._api_stamp(account->>'created_at') IS DISTINCT FROM stamp THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'account differs from command';
    END IF;
    accounts := accounts || jsonb_build_object(target, account);
  ELSE
    account := accounts->target;
    IF account IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'account missing';
    END IF;
  END IF;
  IF action = 'set_active' THEN
    IF account->>'role' = 'owner' THEN
      RAISE EXCEPTION USING ERRCODE = 'PT403', MESSAGE = 'owner deactivation denied';
    END IF;
    accounts := jsonb_set(accounts, ARRAY[target,'active'], p->'active', false);
  ELSE
    IF digest IS NULL OR digest !~ '^[0-9a-f]{64}$' OR keys ? digest THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'invalid new key';
    END IF;
    days := CASE WHEN account->>'role' = 'owner' THEN 90 ELSE 30 END;
    issued := new_doc->'keys'->digest;
    IF issued->>'account_id' IS DISTINCT FROM target
       OR "preflight_team"._api_stamp(issued->>'expires_at') IS DISTINCT FROM stamp + make_interval(days => days) THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'key differs from command';
    END IF;
    SELECT coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb) INTO keys
      FROM jsonb_each(keys) e WHERE e.value->>'account_id' <> target;
    keys := keys || jsonb_build_object(digest, issued);
  END IF;
  IF new_doc->'accounts' IS DISTINCT FROM accounts OR new_doc->'keys' IS DISTINCT FROM keys THEN
    RAISE EXCEPTION USING ERRCODE = 'PT403', MESSAGE = 'authentication delta denied';
  END IF;
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team".lock_workspace(access_key text, request_id uuid, command_text text)
RETURNS TABLE(revision bigint, document jsonb, db_now timestamptz)
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE cmd jsonb;
BEGIN
  cmd := "preflight_team"._api_command(request_id,command_text);
  SELECT w.revision,w.document INTO revision,document FROM "preflight_team".workspace w WHERE w.singleton = true FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT500', MESSAGE = 'workspace missing'; END IF;
  PERFORM "preflight_team"._api_state(revision,document);
  PERFORM "preflight_team"._api_auth(document,access_key,cmd->>'action');
  db_now := clock_timestamp();
  RETURN NEXT;
END $fn$;

CREATE OR REPLACE FUNCTION "preflight_team".save_workspace(access_key text, request_id uuid, command_text text, expected_revision bigint, updated_document jsonb)
RETURNS bigint
LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp SET TimeZone = 'UTC'
AS $fn$
DECLARE old_revision bigint; old_doc jsonb; cmd jsonb; actor jsonb; action text; receipt_id text;
        fingerprint text; previous jsonb; receipt jsonb; stamp timestamptz; is_read boolean; is_security boolean;
BEGIN
  cmd := "preflight_team"._api_command(request_id,command_text); action := cmd->>'action';
  SELECT w.revision,w.document INTO old_revision,old_doc FROM "preflight_team".workspace w WHERE w.singleton = true FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT500', MESSAGE = 'workspace missing'; END IF;
  PERFORM "preflight_team"._api_state(old_revision,old_doc);
  actor := "preflight_team"._api_auth(old_doc,access_key,action);
  IF expected_revision IS NULL OR expected_revision IS DISTINCT FROM old_revision THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'revision conflict';
  END IF;
  fingerprint := encode(sha256(convert_to(command_text,'UTF8')),'hex');
  receipt_id := (actor->>'id') || ':' || request_id::text;
  previous := old_doc->'receipts'->receipt_id;
  IF previous IS NOT NULL THEN
    IF previous->>'fingerprint' IS DISTINCT FROM fingerprint THEN
      RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'request conflict';
    END IF;
    IF updated_document IS DISTINCT FROM old_doc THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'replay cannot modify state';
    END IF;
    RETURN old_revision;
  END IF;
  is_read := action IN ('overview','view','accounts','disagreements','export');
  is_security := action IN ('replace_key','set_active') AND actor->>'role' = 'owner';
  IF updated_document IS NOT DISTINCT FROM old_doc THEN
    IF NOT is_read THEN RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'mutation requires a receipt'; END IF;
    RETURN old_revision;
  END IF;
  PERFORM "preflight_team"._api_state(old_revision + 1,updated_document);
  IF is_read THEN
    IF updated_document->'receipts' IS DISTINCT FROM old_doc->'receipts' THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'read cannot change receipts';
    END IF;
    stamp := clock_timestamp();
  ELSE
    receipt := updated_document->'receipts'->receipt_id;
    IF jsonb_typeof(receipt) IS DISTINCT FROM 'object'
       OR receipt - ARRAY['fingerprint','action','at','result'] <> '{}'::jsonb
       OR receipt->>'fingerprint' IS DISTINCT FROM fingerprint OR receipt->>'action' IS DISTINCT FROM action
       OR jsonb_typeof(receipt->'result') IS DISTINCT FROM 'object'
       OR receipt#>'{result,revision}' IS DISTINCT FROM to_jsonb(old_revision + 1)
       OR ((updated_document->'receipts') - receipt_id) IS DISTINCT FROM old_doc->'receipts' THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'receipt delta denied';
    END IF;
    stamp := "preflight_team"._api_stamp(receipt->>'at');
    IF stamp < transaction_timestamp() OR stamp > clock_timestamp() THEN
      RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'receipt timestamp outside transaction';
    END IF;
    IF action IN ('create_account','replace_key','set_active') THEN
      IF receipt#>>'{result,account_id}' IS DISTINCT FROM cmd#>>'{payload,account_id}' THEN
        RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'receipt target differs';
      END IF;
      IF action = 'create_account' AND receipt#>'{result,account}' IS DISTINCT FROM updated_document->'accounts'->(cmd#>>'{payload,account_id}') THEN
        RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'receipt account differs';
      END IF;
      IF action = 'set_active' AND receipt#>'{result,active}' IS DISTINCT FROM cmd#>'{payload,active}' THEN
        RAISE EXCEPTION USING ERRCODE = 'PT422', MESSAGE = 'receipt active flag differs';
      END IF;
    END IF;
    IF NOT is_security AND (SELECT count(*) FROM jsonb_object_keys(old_doc->'receipts')) >= 10000 THEN
      RAISE EXCEPTION USING ERRCODE = 'PT507', MESSAGE = 'receipt capacity reached';
    END IF;
  END IF;
  PERFORM "preflight_team"._api_auth_delta(old_doc,updated_document,actor,cmd,stamp);
  IF NOT is_read AND NOT is_security AND octet_length(convert_to(updated_document::text,'UTF8')) > 30000000 THEN
    RAISE EXCEPTION USING ERRCODE = 'PT507', MESSAGE = 'state capacity reached';
  END IF;
  UPDATE "preflight_team".workspace SET revision = old_revision + 1, document = updated_document, updated_at = clock_timestamp()
    WHERE singleton = true AND revision = expected_revision;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'revision conflict'; END IF;
  RETURN old_revision + 1;
END $fn$;

DO $bootstrap_guard$
DECLARE rev bigint; doc jsonb; credential jsonb; audit_id text; audit jsonb;
BEGIN
  SELECT revision,document INTO STRICT rev,doc FROM "preflight_team".workspace WHERE singleton=true;
  PERFORM "preflight_team"._api_state(rev,doc);
  IF rev <> 1 OR (SELECT count(*) FROM jsonb_object_keys(doc->'accounts')) <> 1
     OR (SELECT count(*) FROM jsonb_object_keys(doc->'keys')) <> 1
     OR (SELECT count(*) FROM jsonb_object_keys(doc->'receipts')) <> 1
     OR doc#>'{accounts,acct_owner,active}' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'prepared state is not an initial owner bootstrap';
  END IF;
  SELECT value INTO STRICT credential FROM jsonb_each(doc->'keys');
  SELECT key,value INTO STRICT audit_id,audit FROM jsonb_each(doc->'receipts');
  IF credential->>'account_id' IS DISTINCT FROM 'acct_owner'
     OR "preflight_team"._api_stamp(credential->>'expires_at') <= clock_timestamp()
     OR "preflight_team"._api_stamp(credential->>'expires_at') IS DISTINCT FROM "preflight_team"._api_stamp(doc#>>'{accounts,acct_owner,created_at}') + interval '90 days'
     OR audit_id !~ '^database_admin:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR audit->>'action' IS DISTINCT FROM 'bootstrap'
     OR audit->>'authority' IS DISTINCT FROM 'database_admin'
     OR audit->>'database_user' IS DISTINCT FROM 'preflight_owner'
     OR (audit->>'fingerprint') IS NULL OR audit->>'fingerprint' !~ '^[0-9a-f]{64}$'
     OR audit->'previous_revision' IS DISTINCT FROM '0'::jsonb
     OR audit->'revoked_owner_keys' IS DISTINCT FROM '0'::jsonb
     OR audit#>'{result,revision}' IS DISTINCT FROM '1'::jsonb
     OR audit#>>'{result,account_id}' IS DISTINCT FROM 'acct_owner'
     OR audit#>>'{result,expires_at}' IS DISTINCT FROM credential->>'expires_at' THEN
    RAISE EXCEPTION 'prepared owner credential or bootstrap receipt does not match contract';
  END IF;
END $bootstrap_guard$

DO $final_guard$
DECLARE privilege text; entry record; actual record;
BEGIN
  IF current_user IS DISTINCT FROM 'preflight_owner' OR session_user IS DISTINCT FROM 'preflight_owner' THEN
    RAISE EXCEPTION 'administrator role was not restored';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='preflight_runtime' AND rolcanlogin AND NOT (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls OR rolinherit))
     OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='preflight_team_api_owner' AND NOT (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls OR rolinherit))
     OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles p ON p.oid=m.member WHERE p.rolname IN ('preflight_runtime','preflight_team_api_owner'))
     OR pg_catalog.pg_has_role(current_user,'preflight_team_api_owner','SET')
     OR pg_catalog.pg_has_role(current_user,'preflight_team_api_owner','USAGE')
     OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE roleid='preflight_team_api_owner'::regrole AND member=current_user::regrole AND grantor=current_user::regrole) THEN
    RAISE EXCEPTION 'role boundary or temporary membership restoration failed';
  END IF;
  FOREACH privilege IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
    IF pg_catalog.has_table_privilege('preflight_runtime','preflight_team.workspace',privilege) THEN
      RAISE EXCEPTION 'runtime has table privilege';
    END IF;
  END LOOP;
  FOREACH privilege IN ARRAY ARRAY['SELECT','INSERT','UPDATE','REFERENCES'] LOOP
    IF pg_catalog.has_any_column_privilege('preflight_runtime','preflight_team.workspace',privilege) THEN
      RAISE EXCEPTION 'runtime has column privilege';
    END IF;
  END LOOP;
  IF NOT pg_catalog.has_schema_privilege('preflight_runtime','preflight_team','USAGE')
     OR pg_catalog.has_schema_privilege('preflight_runtime','preflight_team','CREATE')
     OR pg_catalog.has_schema_privilege('preflight_team_api_owner','preflight_team','CREATE')
     OR (SELECT count(*) FROM pg_catalog.pg_proc WHERE pronamespace='preflight_team'::regnamespace) <> 7 THEN
    RAISE EXCEPTION 'schema/function surface differs from contract';
  END IF;
  FOR entry IN SELECT * FROM (VALUES
    ('"preflight_team"."_api_stamp"(text)','824c33ba0c37c77daf468f3b5ea43419c4fa3a349a5eb6689c0fe7a91ec054b1',false),
    ('"preflight_team"."_api_state"(bigint,jsonb)','90c3fea67cc1d40a57ebfaf7157f2a48004a1c3d21fcae10a1ce5c26f71c009c',false),
    ('"preflight_team"."_api_command"(uuid,text)','3f0a26d016eb0de9b7a8e6b8b89f9972b537c566c213c0aa0ab3f8a6375f8980',false),
    ('"preflight_team"."_api_auth"(jsonb,text,text)','2c65c7cdd77c653a4a3bf5fb1a99d320474460e6b314480ff93e41f90f4ccf20',false),
    ('"preflight_team"."_api_auth_delta"(jsonb,jsonb,jsonb,jsonb,timestamp with time zone)','6ca20557805fefb55a2d4e279964233ebd8f52691e36cbffd63f241751254da3',false),
    ('"preflight_team"."lock_workspace"(text,uuid,text)','e74f5a7389fdb34a5a68ec2baf61106f3f05030e564132fbcc3f2b0f6a993ce3',true),
    ('"preflight_team"."save_workspace"(text,uuid,text,bigint,jsonb)','4c3805e4c2fa680ace0c61db2d9c8d65e521122555f9e07b1513e2fd7b4b1cdf',true)
  ) expected(signature,body_hash,is_entry) LOOP
    SELECT p.*, l.lanname INTO actual FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang
      WHERE p.oid=pg_catalog.to_regprocedure(entry.signature);
    IF NOT FOUND OR actual.proowner IS DISTINCT FROM 'preflight_team_api_owner'::regrole::oid
       OR actual.prosecdef IS DISTINCT FROM entry.is_entry OR actual.lanname IS DISTINCT FROM 'plpgsql'
       OR actual.provolatile IS DISTINCT FROM 'v' OR actual.proparallel IS DISTINCT FROM 'u'
       OR NOT coalesce(actual.proconfig @> ARRAY['search_path=pg_catalog, pg_temp','TimeZone=UTC'],false)
       OR encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM entry.body_hash
       OR pg_catalog.has_function_privilege('preflight_runtime',entry.signature,'EXECUTE') IS DISTINCT FROM entry.is_entry
       OR EXISTS(SELECT 1 FROM pg_catalog.aclexplode(coalesce(actual.proacl,pg_catalog.acldefault('f',actual.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') THEN
      RAISE EXCEPTION 'function definition or ACL differs from frozen source';
    END IF;
  END LOOP;
END $final_guard$
